{-| @Backend.Runtime.Kernel.Mac — HMAC, PBKDF2 and length-only-timed equality. -}
module Pudu.Backend.Runtime.Kernel.Mac (macKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
macKernelParts :: [(Text, [Text], [Text])]
macKernelParts =
  [ ("hmac_sha256", ["sha256"],
      [ "/* HMAC-SHA-256 with the padded key hashed once into two states. */"
      , "typedef struct { pudu_sha256 inner, outer; } pudu_hmac_sha256;"
      , "static void pudu_hmac_sha256_key(pudu_hmac_sha256 *mac, pudu_text key) {"
      , "  unsigned char block[64] = {0}, pad[64];"
      , "  if (key.length > 64) {"
      , "    pudu_sha256_start(&mac->inner);"
      , "    pudu_sha256_feed(&mac->inner, key.bytes, key.length);"
      , "    pudu_sha256_finish(&mac->inner, block);"
      , "  } else if (key.length != 0) memcpy(block, key.bytes, key.length);"
      , "  for (int i = 0; i < 64; ++i) pad[i] = block[i] ^ 0x36;"
      , "  pudu_sha256_start(&mac->inner);"
      , "  pudu_sha256_feed(&mac->inner, pad, 64);"
      , "  for (int i = 0; i < 64; ++i) pad[i] = block[i] ^ 0x5c;"
      , "  pudu_sha256_start(&mac->outer);"
      , "  pudu_sha256_feed(&mac->outer, pad, 64);"
      , "}"
      , "/* The tag of a message given as two pieces. */"
      , "static void pudu_hmac_sha256_tag(const pudu_hmac_sha256 *mac, const unsigned char *first, size_t first_length, const unsigned char *second, size_t second_length, unsigned char *tag) {"
      , "  pudu_sha256 inner = mac->inner, outer = mac->outer;"
      , "  unsigned char digest[32];"
      , "  pudu_sha256_feed(&inner, first, first_length);"
      , "  pudu_sha256_feed(&inner, second, second_length);"
      , "  pudu_sha256_finish(&inner, digest);"
      , "  pudu_sha256_feed(&outer, digest, 32);"
      , "  pudu_sha256_finish(&outer, tag);"
      , "}"
      ])
  , ("hmac_sha256_of", ["hmac_sha256", "kernel_pack"],
      [ "static pudu_box *pudu_hmac_sha256_of(pudu_box *key, pudu_box *message) {"
      , "  pudu_hmac_sha256 mac;"
      , "  unsigned char tag[32];"
      , "  pudu_hmac_sha256_key(&mac, key->fields[0].text);"
      , "  pudu_hmac_sha256_tag(&mac, message->fields[0].text.bytes, message->fields[0].text.length, NULL, 0, tag);"
      , "  return pudu_kernel_pack(tag, sizeof tag);"
      , "}"
      ])
  , ("hmac_sha512_of", ["sha512", "kernel_pack"],
      [ "static pudu_box *pudu_hmac_sha512_of(pudu_box *key, pudu_box *message) {"
      , "  pudu_text secret = key->fields[0].text;"
      , "  pudu_sha512 hash;"
      , "  unsigned char block[128] = {0}, pad[128], digest[64];"
      , "  if (secret.length > 128) {"
      , "    pudu_sha512_start(&hash);"
      , "    pudu_sha512_feed(&hash, secret.bytes, secret.length);"
      , "    pudu_sha512_finish(&hash, block);"
      , "  } else if (secret.length != 0) memcpy(block, secret.bytes, secret.length);"
      , "  for (int i = 0; i < 128; ++i) pad[i] = block[i] ^ 0x36;"
      , "  pudu_sha512_start(&hash);"
      , "  pudu_sha512_feed(&hash, pad, 128);"
      , "  pudu_sha512_feed(&hash, message->fields[0].text.bytes, message->fields[0].text.length);"
      , "  pudu_sha512_finish(&hash, digest);"
      , "  for (int i = 0; i < 128; ++i) pad[i] = block[i] ^ 0x5c;"
      , "  pudu_sha512_start(&hash);"
      , "  pudu_sha512_feed(&hash, pad, 128);"
      , "  pudu_sha512_feed(&hash, digest, 64);"
      , "  pudu_sha512_finish(&hash, digest);"
      , "  return pudu_kernel_pack(digest, sizeof digest);"
      , "}"
      ])
  , ("derive_key", ["hmac_sha256", "kernel_signed", "bytes_wrap", "text_allocate"],
      [ "/* PBKDF2 over HMAC-SHA-256; rounds and the wanted length are checked before. */"
      , "static pudu_box *pudu_derive_key(pudu_box *password, pudu_box *salt, pudu_int rounds, pudu_int wanted) {"
      , "  pudu_hmac_sha256 mac;"
      , "  size_t length = (size_t)pudu_kernel_signed(wanted.bits);"
      , "  int64_t turns = pudu_kernel_signed(rounds.bits);"
      , "  unsigned char *out;"
      , "  pudu_text derived = pudu_text_allocate(length, &out);"
      , "  pudu_hmac_sha256_key(&mac, password->fields[0].text);"
      , "  for (uint32_t index = 1; length != 0; ++index) {"
      , "    unsigned char counter[4] = {(unsigned char)(index >> 24), (unsigned char)(index >> 16), (unsigned char)(index >> 8), (unsigned char)index};"
      , "    unsigned char held[32], mixed[32];"
      , "    size_t take = length < 32 ? length : 32;"
      , "    pudu_hmac_sha256_tag(&mac, salt->fields[0].text.bytes, salt->fields[0].text.length, counter, 4, held);"
      , "    memcpy(mixed, held, 32);"
      , "    for (int64_t turn = 1; turn < turns; ++turn) {"
      , "      pudu_hmac_sha256_tag(&mac, held, 32, NULL, 0, held);"
      , "      for (int i = 0; i < 32; ++i) mixed[i] ^= held[i];"
      , "    }"
      , "    memcpy(out, mixed, take);"
      , "    out += take;"
      , "    length -= take;"
      , "  }"
      , "  return pudu_bytes_wrap(derived);"
      , "}"
      ])
  , ("constant_time_equal", [],
      [ "/* Equal lengths and no differing byte, without stopping at the first one. */"
      , "static int pudu_constant_time_equal(pudu_box *left, pudu_box *right) {"
      , "  pudu_text a = left->fields[0].text, b = right->fields[0].text;"
      , "  unsigned difference = 0;"
      , "  if (a.length != b.length) return 0;"
      , "  for (size_t i = 0; i < a.length; ++i) difference |= (unsigned)(a.bytes[i] ^ b.bytes[i]);"
      , "  return difference == 0;"
      , "}"
      ])
  ]
